USE GRAPH CorpusKG 
INTERPRET OPENCYPHER QUERY () {
MATCH (s1:OlympicEvent)
WHERE toLower(s1.name) CONTAINS "30 kilometre" AND toLower(s1.name) CONTAINS "pursuit" AND toLower(s1.name) CONTAINS "men"
RETURN s1.name AS olympic_event_name, s1.gold AS gold_medalist_nam
}

